import math
import re
from decimal import Decimal, InvalidOperation


_TERM = re.compile(r"(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)(?:ms|s|m|h|d)")
_FACTORS = {
    "ms": Decimal(1),
    "s": Decimal(1000),
    "m": Decimal(60000),
    "h": Decimal(3600000),
    "d": Decimal(86400000),
}


def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip()
    if not text:
        raise ValueError("duration must not be empty")

    total = Decimal(0)
    position = 0
    length = len(text)
    while position < length:
        # Whitespace is permitted only between complete terms.
        if text[position].isspace():
            while position < length and text[position].isspace():
                position += 1
            if position == length:
                break

        match = _TERM.match(text, position)
        if match is None:
            raise ValueError("invalid duration")
        term = match.group()
        unit = next(unit for unit in ("ms", "s", "m", "h", "d") if term.endswith(unit))
        number = term[:-len(unit)]
        try:
            total += Decimal(number) * _FACTORS[unit]
        except InvalidOperation as exc:
            raise ValueError("invalid duration") from exc
        position = match.end()

        if position < length and not text[position].isspace():
            # The next term may begin immediately, but must match in full.
            continue

    return int(total.to_integral_value(rounding="ROUND_CEILING"))

